package com.franco.desco.adapter.in.web.pricing;import com.franco.desco.application.pricing.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.pricing.PricingModels;import org.springframework.stereotype.Component;
@Component public class PricingWebMapper{public PricingCommands.ListConditions conditions(int p,int t){return new PricingCommands.ListConditions(new PageRequest<>(p,t,null,null,null));}public PricingCommands.ListPrices prices(int p,int t,Long camp,Long op,Integer var,Long cond){return new PricingCommands.ListPrices(new PageRequest<>(p,t,new PricingCommands.PriceFilter(camp,op,var,cond),null,null));}public PricingResponses.Condition response(PricingModels.Condition x){return new PricingResponses.Condition(x.condicionComercialId(),x.codigo(),x.nombre(),x.descripcion(),x.pesoMinimoG(),x.pesoMaximoG(),x.modalidadVentaId(),x.codigoModalidad(),x.modalidad(),x.estado(),x.usos());}public PricingResponses.Price response(PricingModels.Price x){return new PricingResponses.Price(x.precioComercialId(),x.campaniaVentaId(),x.campania(),x.operativoVentaId(),x.operativo(),x.variedadPaltaId(),x.variedad(),x.condicionComercialId(),x.condicion(),x.precio(),x.moneda(),x.unidadMedida(),x.fechaVigenciaDesde(),x.fechaVigenciaHasta(),x.version(),x.vigente());}public PricingResponses.PriceVersion response(PricingModels.PriceVersion x){return new PricingResponses.PriceVersion(x.precioComercialId(),x.precio(),x.moneda(),x.unidadMedida(),x.fechaVigenciaDesde(),x.fechaVigenciaHasta(),x.version(),x.estado());}}
